const hhmm = () => new Date().toTimeString().slice(0, 5);
const jourISO = (d) => d.toISOString().slice(0, 10);

function Ecran(props) {
  const itv = useCollection("interventions");
  const tch = useCollection("taches");
  const rap = useCollection("rapports");
  const sit = useCollection("sites");
  const eqp = useCollection("equipes");
  const [rapport, setRapport] = useState(null);
  const [obs, setObs] = useState("");
  const [envoi, setEnvoi] = useState(false);

  const aujourdhui = jourISO(new Date());
  const loading = itv.loading || tch.loading || rap.loading || sit.loading || eqp.loading;

  const nomSite = (id) => (sit.rows.find((s) => s.ref === id || s.id === id) || {}).nom || "Site inconnu";
  const nomEquipe = (id) => (eqp.rows.find((e) => e.ref === id || e.id === id) || {}).nom || "Équipe inconnue";

  const passages = useMemo(
    () => itv.rows.filter((i) => i.date === aujourdhui && i.statut !== "Annulée")
      .sort((a, b) => (a.heure_prevue || "").localeCompare(b.heure_prevue || "")),
    [itv.rows, aujourdhui]
  );
  const retards = useMemo(
    () => tch.rows.filter((t) => t.statut !== "Fait" && t.echeance && t.echeance < aujourdhui)
      .sort((a, b) => a.echeance.localeCompare(b.echeance)),
    [tch.rows, aujourdhui]
  );
  const aEnvoyer = useMemo(() => {
    const faits = new Set(rap.rows.filter((r) => r.statut_envoi === "Envoyé").map((r) => r.intervention_id));
    return itv.rows.filter((i) => i.statut === "Terminée" && !faits.has(i.ref) && !faits.has(i.id))
      .sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  }, [itv.rows, rap.rows]);

  const enCours = passages.filter((p) => p.statut === "En cours").length;
  const terminesJour = passages.filter((p) => p.statut === "Terminée").length;

  const pointer = async (i, champ) => {
    try {
      const data = champ === "arrivee" ? { arrivee: hhmm(), statut: "En cours" } : { depart: hhmm(), statut: "Terminée" };
      await itv.update(i.id, data);
      toast(champ === "arrivee" ? "Arrivée pointée à " + data.arrivee : "Départ pointé à " + data.depart, "ok");
    } catch (e) {
      toast(e.message, "bad");
    }
  };

  const relancer = async (t) => {
    try {
      await tch.update(t.id, { statut: "En cours" });
      toast("Tâche « " + t.intitule + " » relancée", "ok");
    } catch (e) {
      toast(e.message, "bad");
    }
  };

  const terminer = async (t) => {
    await tch.update(t.id, { statut: "Fait" });
    toast("Tâche terminée", "ok");
  };

  const ouvrirRapport = (i) => {
    setObs("");
    setRapport(i);
  };

  const envoyer = async () => {
    const i = rapport;
    const site = sit.rows.find((s) => s.ref === i.site_id || s.id === i.site_id) || {};
    if (!site.contact_email) {
      avertir("Ce site n'a pas d'adresse e-mail de contact. Ajoutez-la dans « Sites clients ».");
      return;
    }
    setEnvoi(true);
    try {
      const texte = obs || "Passage effectué sans remarque particulière.";
      await email({
        a: site.contact_email,
        sujet: "Compte rendu de passage du " + fmt.date(i.date) + " - " + site.nom,
        texte: "Bonjour,\n\nVeuillez trouver le compte rendu du passage de l'équipe " + nomEquipe(i.equipe_id) + " du " + fmt.date(i.date) + " sur " + site.nom + ".\n\n" + texte + "\n\nCordialement,\n" + user.nom,
      });
      await rap.add({
        intervention_id: i.ref || i.id, site_id: i.site_id, date_passage: i.date,
        destinataire: site.contact_email, observations: texte, statut_envoi: "Envoyé", date_envoi: aujourdhui,
      });
      pdf({
        titre: "Compte rendu de passage", sousTitre: site.nom,
        emetteur: { titre: "Conciergo", lignes: [user.nom, user.email] },
        destinataire: { titre: site.contact_nom || "Client", lignes: [site.adresse || "", site.contact_email] },
        lignes: [
          ["Date", fmt.date(i.date)], ["Équipe", nomEquipe(i.equipe_id)],
          ["Arrivée", i.arrivee || "-"], ["Départ", i.depart || "-"],
        ],
        paragraphes: [texte], nomFichier: "compte-rendu-" + i.date,
      });
      toast("Compte rendu envoyé à " + site.contact_email, "ok");
      setRapport(null);
    } catch (e) {
      toast(e.message, "bad");
    }
    setEnvoi(false);
  };

  if (loading) return html`<${ui.Page} titre="Tableau de bord"><${ui.Loading} /></${ui.Page}>`;

  const sous = passages.length
    ? passages.length + " passage" + (passages.length > 1 ? "s" : "") + " aujourd'hui, " + enCours + " en cours, " + terminesJour + " terminé" + (terminesJour > 1 ? "s" : "") + ". " + retards.length + " tâche" + (retards.length > 1 ? "s" : "") + " en retard."
    : "Aucun passage prévu aujourd'hui. " + retards.length + " tâche" + (retards.length > 1 ? "s" : "") + " en retard.";

  const bouton = (i) => {
    if (i.statut === "Planifiée") return html`<${ui.Button} variant="primary" onClick=${() => pointer(i, "arrivee")}>Pointer l'arrivée</${ui.Button}>`;
    if (i.statut === "En cours") return html`<${ui.Button} variant="secondary" onClick=${() => pointer(i, "depart")}>Pointer le départ</${ui.Button}>`;
    return html`<${ui.Badge} couleur="vert">Terminé</${ui.Badge}>`;
  };

  return html`
    <${ui.Page} titre="Tableau de bord" sous=${sous}
      actions=${html`<${ui.Button} variant="secondary" onClick=${() => go("planning")}>Ouvrir le planning</${ui.Button}>`}>
      <div class="grid lg:grid-cols-[1fr_340px] gap-6">
        <div class="space-y-6 min-w-0">
          <${ui.Card} titre="Passages du jour">
            ${passages.length === 0
              ? html`<${ui.Empty} texte="Aucun passage n'est planifié aujourd'hui. Planifiez une intervention pour vos équipes."
                  action=${html`<${ui.Button} variant="primary" onClick=${() => go("planning")}>Planifier un passage</${ui.Button}>`} />`
              : html`<ul class="divide-y divide-[var(--bordure,#A7F3D0)]">
                  ${passages.map((i) => html`
                    <li key=${i.id} class="py-4 flex flex-wrap items-center gap-3 justify-between">
                      <div class="min-w-0">
                        <div class="text-[15px] font-semibold text-[#064E3B] truncate">${nomSite(i.site_id)}</div>
                        <div class="text-sm text-[#475569]">
                          ${nomEquipe(i.equipe_id)} · prévu à ${i.heure_prevue || "-"} · ${i.duree_minutes || 0} min
                        </div>
                        ${(i.arrivee || i.depart) && html`<div class="text-sm text-[#475569]">
                          ${i.arrivee ? "Arrivée " + i.arrivee : ""}${i.depart ? " · Départ " + i.depart : ""}
                        </div>`}
                      </div>
                      <div class="flex items-center gap-2">${bouton(i)}</div>
                    </li>`)}
                </ul>`}
          </${ui.Card}>

          <${ui.Card} titre="Rapports restant à envoyer">
            ${aEnvoyer.length === 0
              ? html`<${ui.Empty} texte="Tous les passages terminés ont reçu leur compte rendu." />`
              : html`<ul class="divide-y divide-[#A7F3D0]">
                  ${aEnvoyer.map((i) => html`
                    <li key=${i.id} class="py-4 flex flex-wrap items-center gap-3 justify-between">
                      <div class="min-w-0">
                        <div class="text-[15px] font-semibold text-[#064E3B] truncate">${nomSite(i.site_id)}</div>
                        <div class="text-sm text-[#475569]">Passage du ${fmt.date(i.date)} · ${nomEquipe(i.equipe_id)}</div>
                      </div>
                      <${ui.Button} variant="primary" icone="mail" onClick=${() => ouvrirRapport(i)}>Rédiger et envoyer</${ui.Button}>
                    </li>`)}
                </ul>`}
          </${ui.Card}>
        </div>

        <div class="space-y-6 min-w-0">
          <${ui.Card} titre=${"Tâches en retard (" + retards.length + ")"}>
            ${retards.length === 0
              ? html`<${ui.Empty} texte="Aucune tâche en retard. Bravo !" />`
              : html`<ul class="divide-y divide-[#A7F3D0]">
                  ${retards.map((t) => html`
                    <li key=${t.id} class="py-3 space-y-2">
                      <div class="flex items-start justify-between gap-2">
                        <div class="min-w-0">
                          <div class="text-sm font-semibold text-[#064E3B]">${t.intitule}</div>
                          <div class="text-sm text-[#475569]">${nomSite(t.site_id)}</div>
                        </div>
                        <${ui.Badge} couleur="rouge">${fmt.date(t.echeance)}</${ui.Badge}>
                      </div>
                      <div class="flex gap-2">
                        ${t.statut === "À faire" && html`<${ui.Button} variant="secondary" onClick=${() => relancer(t)}>Relancer</${ui.Button}>`}
                        <${ui.Button} variant="ghost" onClick=${() => terminer(t)}>Marquer fait</${ui.Button}>
                      </div>
                    </li>`)}
                </ul>`}
          </${ui.Card}>
        </div>
      </div>

      <${ui.Modal} open=${!!rapport} onClose=${() => setRapport(null)} titre="Compte rendu de passage"
        actions=${html`
          <${ui.Button} variant="ghost" onClick=${() => setRapport(null)}>Annuler</${ui.Button}>
          <${ui.Button} variant="primary" disabled=${envoi} onClick=${envoyer}>${envoi ? "… en cours" : "Envoyer par e-mail et télécharger le PDF"}</${ui.Button}>`}>
        ${rapport && html`
          <div class="space-y-3">
            <p class="text-sm text-[#475569]">
              ${nomSite(rapport.site_id)} · passage du ${fmt.date(rapport.date)} · ${nomEquipe(rapport.equipe_id)}
            </p>
            <${ui.Textarea} label="Observations pour le client" value=${obs} onInput=${setObs} rows=${5} />
          </div>`}
      </${ui.Modal}>
    </${ui.Page}>`;
}

const TYPES = ["Cabinet", "Agence", "Coworking", "PME"];

const CHAMPS = [
  { nom: "nom", label: "Nom du site", type: "texte", requis: true },
  { nom: "type_site", label: "Type de site", type: "choix", options: TYPES },
  { nom: "adresse", label: "Adresse", type: "texte", requis: true },
  { nom: "contact_nom", label: "Contact sur place", type: "texte" },
  { nom: "contact_email", label: "E-mail du contact", type: "email" },
  { nom: "contact_telephone", label: "Téléphone du contact", type: "tel" },
  { nom: "consignes", label: "Consignes d'entretien", type: "long" },
];

const COULEUR_STATUT = { "Terminée": "vert", "En cours": "bleu", "Planifiée": "gris", "Annulée": "rouge" };

function Info({ label, children }) {
  return html`<div class="py-2">
    <div class="text-xs text-[#475569]">${label}</div>
    <div class="text-sm text-[#064E3B] break-words">${children || "—"}</div>
  </div>`;
}

function Ecran(props) {
  const sites = useCollection("sites");
  const interventions = useCollection("interventions");
  const equipes = useCollection("equipes");
  const rapports = useCollection("rapports");
  const [recherche, setRecherche] = useState("");
  const [type, setType] = useState("tous");
  const [ajout, setAjout] = useState(false);
  const [edition, setEdition] = useState(null);
  const [fiche, setFiche] = useState(null);

  const cles = (s) => [s.id, s.ref].filter(Boolean);
  const dePasses = (s) =>
    interventions.rows
      .filter((i) => cles(s).includes(i.site_id))
      .sort((a, b) => String(b.date).localeCompare(String(a.date)));

  const filtres = useMemo(() => {
    const q = recherche.trim().toLowerCase();
    return sites.rows.filter((s) => {
      if (type !== "tous" && s.type_site !== type) return false;
      if (!q) return true;
      return [s.nom, s.type_site, s.adresse, s.contact_nom].some((v) => String(v || "").toLowerCase().includes(q));
    });
  }, [sites.rows, recherche, type]);

  const nomEquipe = (id) => {
    const e = equipes.rows.find((x) => x.id === id || x.ref === id);
    return e ? e.nom : "—";
  };

  const enregistrer = async (donnees) => {
    try {
      if (edition) {
        await sites.update(edition.id, donnees);
        toast("Site mis à jour", "ok");
      } else {
        await sites.add(donnees);
        toast("Site ajouté", "ok");
      }
      setAjout(false);
      setEdition(null);
      setFiche(null);
    } catch (e) {
      toast(e.message, "bad");
    }
  };

  const supprimer = async (s) => {
    if (!await demander("Supprimer le site « " + s.nom + " » ?", { ok: "Supprimer", danger: true })) return;
    try {
      await sites.remove(s.id);
      setFiche(null);
      toast("Site supprimé", "ok");
    } catch (e) {
      toast(e.message, "bad");
    }
  };

  if (sites.loading) return html`<${ui.Page} titre="Sites clients"><${ui.Loading} /></${ui.Page}>`;

  const passes = fiche ? dePasses(fiche) : [];
  const nbRapports = fiche ? rapports.rows.filter((r) => cles(fiche).includes(r.site_id)).length : 0;
  const sous = sites.rows.length
    ? filtres.length + " site" + (filtres.length > 1 ? "s" : "") + " affiché" + (filtres.length > 1 ? "s" : "") + " sur " + sites.rows.length + "."
    : "Aucun site client pour l'instant : ajoutez le premier.";

  const colonnes = [
    { cle: "nom", label: "Site", rendu: (s) => html`<span class="font-semibold text-[#064E3B]">${s.nom}</span>` },
    { cle: "type_site", label: "Type", rendu: (s) => html`<${ui.Badge} couleur="vert">${s.type_site || "—"}</${ui.Badge}>` },
    { cle: "adresse", label: "Adresse" },
    { cle: "contact_nom", label: "Contact" },
    { cle: "passages", label: "Passages", rendu: (s) => dePasses(s).length },
  ];

  return html`<${ui.Page} titre="Sites clients" sous=${sous}
    actions=${html`<${ui.Button} variant="primary" onClick=${() => setAjout(true)}>Ajouter un site</${ui.Button}>`}>
    <div class="flex flex-col sm:flex-row gap-3 mb-4">
      <div class="flex-1">
        <${ui.Input} label="Recherche" value=${recherche} onInput=${setRecherche} placeholder="Nom, type, adresse ou contact" />
      </div>
      <div class="sm:w-56">
        <${ui.Select} label="Type de site" value=${type} onChange=${setType}
          options=${[["tous", "Tous les types"], ...TYPES.map((t) => [t, t])]} />
      </div>
    </div>
    <${ui.Card}>
      ${sites.rows.length === 0
        ? html`<${ui.Empty} texte="Ajoutez votre premier site client avec son adresse et ses contacts."
            action=${html`<${ui.Button} variant="primary" onClick=${() => setAjout(true)}>Ajouter un site</${ui.Button}>`} />`
        : html`<${ui.Table} colonnes=${colonnes} lignes=${filtres} onClick=${setFiche} vide="Aucun site ne correspond à votre recherche." />`}
    </${ui.Card}>

    <${ui.Modal} open=${ajout || !!edition} titre=${edition ? "Modifier le site" : "Nouveau site"}
      onClose=${() => { setAjout(false); setEdition(null); }}>
      <${ui.Formulaire} champs=${CHAMPS} valeur=${edition || { type_site: "Cabinet" }}
        libelle=${edition ? "Enregistrer" : "Ajouter le site"}
        onEnregistrer=${enregistrer} onAnnuler=${() => { setAjout(false); setEdition(null); }} />
    </${ui.Modal}>

    <${ui.Modal} open=${!!fiche && !edition} titre=${fiche ? fiche.nom : ""} onClose=${() => setFiche(null)}
      actions=${fiche && html`
        <${ui.Button} variant="secondary" onClick=${() => setEdition(fiche)}>Modifier</${ui.Button}>
        <${ui.Button} variant="danger" onClick=${() => supprimer(fiche)}>Supprimer</${ui.Button}>`}>
      ${fiche && html`
        <div class="grid sm:grid-cols-2 gap-x-6">
          <${Info} label="Type">${fiche.type_site}</${Info}>
          <${Info} label="Adresse">${fiche.adresse}</${Info}>
          <${Info} label="Contact">${fiche.contact_nom}</${Info}>
          <${Info} label="Téléphone">${fiche.contact_telephone}</${Info}>
          <${Info} label="E-mail">${fiche.contact_email}</${Info}>
          <${Info} label="Rapports envoyés">${nbRapports}</${Info}>
        </div>
        <div class="mt-3 rounded-lg border border-[#A7F3D0] bg-[#ECFDF5] p-3">
          <div class="text-xs text-[#475569] mb-1">Consignes d'entretien</div>
          <div class="text-sm text-[#064E3B] whitespace-pre-line">${fiche.consignes || "Aucune consigne renseignée."}</div>
        </div>
        <h3 class="mt-5 mb-2 text-sm font-semibold text-[#064E3B]">Historique des passages</h3>
        ${passes.length === 0
          ? html`<p class="text-sm text-[#475569]">Aucun passage enregistré pour ce site.</p>`
          : html`<ul class="divide-y divide-[#A7F3D0] max-h-64 overflow-y-auto">
              ${passes.map((i) => html`<li key=${i.id} class="py-3 flex items-center justify-between gap-3">
                <div class="min-w-0">
                  <div class="text-sm font-medium text-[#064E3B]">${fmt.date(i.date)} à ${i.heure_prevue || "—"}</div>
                  <div class="text-xs text-[#475569] truncate">${nomEquipe(i.equipe_id)}${i.arrivee ? " · arrivée " + i.arrivee : ""}${i.depart ? " · départ " + i.depart : ""}</div>
                </div>
                <${ui.Badge} couleur=${COULEUR_STATUT[i.statut] || "gris"}>${i.statut}</${ui.Badge}>
              </li>`)}
            </ul>`}
        <div class="mt-4">
          <${ui.Button} variant="secondary" onClick=${() => go("planning", { site_id: fiche.id })}>Planifier un passage</${ui.Button}>
        </div>`}
    </${ui.Modal}>
  </${ui.Page}>`;
}

const JOURS = ["Lun", "Mar", "Mer", "Jeu", "Ven", "Sam", "Dim"];
const GRILLE = "grid-template-columns: 150px repeat(7, minmax(140px, 1fr))";

function isoJour(d) {
  const p = (n) => String(n).padStart(2, "0");
  return d.getFullYear() + "-" + p(d.getMonth() + 1) + "-" + p(d.getDate());
}

function lundiDe(d) {
  const x = new Date(d.getFullYear(), d.getMonth(), d.getDate());
  x.setDate(x.getDate() - ((x.getDay() + 6) % 7));
  return x;
}

function couleurStatut(s) {
  return { "Planifiée": "bleu", "En cours": "orange", "Terminée": "vert", "Annulée": "gris" }[s] || "gris";
}

function Ecran(props) {
  const inter = useCollection("interventions");
  const sites = useCollection("sites");
  const equipes = useCollection("equipes");
  const [debut, setDebut] = useState(lundiDe(new Date()));
  const [edit, setEdit] = useState(null);
  const [form, setForm] = useState({});
  const [rappel, setRappel] = useState(true);
  const [busy, setBusy] = useState(false);

  const jours = useMemo(() => JOURS.map((l, i) => {
    const d = new Date(debut);
    d.setDate(d.getDate() + i);
    return { label: l, num: d.getDate(), iso: isoJour(d), date: d };
  }), [debut]);

  const sitesRows = sites.rows || [];
  const equipesRows = equipes.rows || [];
  const interRows = inter.rows || [];

  const nomSite = (id) => (sitesRows.find((s) => s.ref === id || s.id === id) || {}).nom || "Site inconnu";
  const nomEquipe = (id) => (equipesRows.find((e) => e.ref === id || e.id === id) || {}).nom || "Équipe inconnue";
  const valSite = (id) => (sitesRows.find((s) => s.ref === id || s.id === id) || {});
  const cle = (r) => r.ref || r.id;
  const parHeure = (a, b) => (a.heure_prevue || "").localeCompare(b.heure_prevue || "");

  const semaine = useMemo(() => interRows.filter((i) => jours.some((j) => j.iso === i.date)), [interRows, jours]);
  const actifs = semaine.filter((i) => i.statut !== "Annulée");
  const minutes = actifs.reduce((t, i) => t + (Number(i.duree_minutes) || 0), 0);
  const aujourdhui = isoJour(new Date());
  const duJour = interRows.filter((i) => i.date === aujourdhui && i.statut !== "Annulée").sort(parHeure);

  const ouvrir = (i, date, equipe) => {
    setRappel(!i);
    setForm(i ? { ...i } : { date: date || aujourdhui, equipe_id: equipe || (equipesRows[0] ? cle(equipesRows[0]) : ""), site_id: sitesRows[0] ? cle(sitesRows[0]) : "", heure_prevue: "08:00", duree_minutes: 60, statut: "Planifiée" });
    setEdit(i || {});
  };
  const maj = (k) => (v) => setForm((f) => ({ ...f, [k]: v }));

  const enregistrer = async () => {
    if (!form.site_id || !form.equipe_id || !form.date) return toast("Choisissez un site, une équipe et une date.", "bad");
    setBusy(true);
    try {
      const data = { site_id: form.site_id, equipe_id: form.equipe_id, date: form.date, heure_prevue: form.heure_prevue || "08:00", duree_minutes: Number(form.duree_minutes) || 60, statut: form.statut || "Planifiée", arrivee: form.arrivee || "", depart: form.depart || "" };
      const site = valSite(form.site_id);
      if (edit.id) {
        if (edit.rappel_id && (data.date !== edit.date || data.heure_prevue !== edit.heure_prevue || data.statut === "Annulée")) {
          try { await annulerEmail(edit.rappel_id); data.rappel_id = ""; } catch (e) {}
        }
        await inter.update(edit.id, data);
      } else {
        if (rappel && site.contact_email) {
          const veille = new Date(form.date + "T08:00:00");
          veille.setDate(veille.getDate() - 1);
          if (veille > new Date()) {
            const r = await email({ a: site.contact_email, sujet: "Rappel : passage de nos équipes le " + fmt.date(form.date), texte: "Bonjour " + (site.contact_nom || "") + ",\n\nNotre équipe " + nomEquipe(form.equipe_id) + " interviendra sur " + site.nom + " le " + fmt.date(form.date) + " à " + data.heure_prevue + " (durée prévue : " + data.duree_minutes + " min).\n\nCordialement", quand: veille.toISOString() });
            data.rappel_id = r.id;
          }
        }
        await inter.add(data);
      }
      toast(edit.id ? "Passage mis à jour." : "Passage planifié.", "ok");
      setEdit(null);
    } catch (e) { toast(e.message || "Enregistrement impossible.", "bad"); }
    setBusy(false);
  };

  const annuler = async (i) => {
    if (!await demander("Annuler ce passage sur " + nomSite(i.site_id) + " ?", { ok: "Annuler le passage", danger: true })) return;
    if (i.rappel_id) { try { await annulerEmail(i.rappel_id); } catch (e) {} }
    await inter.update(i.id, { statut: "Annulée", rappel_id: "" });
    toast("Passage annulé.", "ok");
  };

  const supprimer = async (i) => {
    if (!await demander("Supprimer définitivement ce passage ?", { ok: "Supprimer", danger: true })) return;
    if (i.rappel_id) { try { await annulerEmail(i.rappel_id); } catch (e) {} }
    await inter.remove(i.id);
    setEdit(null);
    toast("Passage supprimé.", "ok");
  };

  const decaler = (n) => { const d = new Date(debut); d.setDate(d.getDate() + n * 7); setDebut(d); };
  const fin = jours[6].date;
  const titreSemaine = fmt.date(isoJour(debut)) + " – " + fmt.date(isoJour(fin));
  const chargement = inter.loading || sites.loading || equipes.loading;
  const lignesEquipes = equipesRows.filter((e) => e.actif !== false);

  const cellule = (e, j) => {
    const liste = semaine.filter((i) => i.date === j.iso && i.equipe_id === cle(e)).sort(parHeure);
    return html`<div class="flex flex-col gap-2 p-2 border-l border-[#A7F3D0] min-h-[76px] self-stretch">
      ${liste.map((i) => html`<button key=${i.id} onClick=${() => ouvrir(i)} class="block shrink-0 w-full text-left rounded-lg border border-[#A7F3D0] bg-white p-2 hover:border-[var(--c)] focus:outline-none focus:ring-2 focus:ring-[var(--c)] cursor-pointer ${i.statut === "Annulée" ? "opacity-50" : ""}">
        <div class="text-xs text-[#475569]">${i.heure_prevue || ""} · ${i.duree_minutes || 0} min</div>
        <div class="text-sm font-medium text-[#064E3B] break-words ${i.statut === "Annulée" ? "line-through" : ""}">${nomSite(i.site_id)}</div>
        <div class="mt-1"><${ui.Badge} couleur=${couleurStatut(i.statut)}>${i.statut || "—"}</${ui.Badge}></div>
      </button>`)}
      <button onClick=${() => ouvrir(null, j.iso, cle(e))} class="block w-full shrink-0 min-h-[44px] rounded-lg border border-dashed border-[#A7F3D0] text-xs text-[#475569] hover:border-[var(--c)] hover:text-[var(--c)] cursor-pointer focus:outline-none focus:ring-2 focus:ring-[var(--c)]">+ Ajouter</button>
    </div>`;
  };

  return html`<${ui.Page} titre="Planning de la semaine" sous=${actifs.length + " passage" + (actifs.length > 1 ? "s" : "") + " prévu" + (actifs.length > 1 ? "s" : "") + " du " + titreSemaine + ", soit " + fmt.num(Math.round(minutes / 60 * 10) / 10) + " h d'intervention."}
    actions=${html`<${ui.Button} variant="primary" onClick=${() => ouvrir(null)}>Planifier un passage</${ui.Button}>`}>
    ${chargement ? html`<${ui.Loading} />` : html`
    <div class="grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_300px] gap-6 max-w-full">
      <div class="min-w-0">
      <${ui.Card} titre=${"Semaine du " + titreSemaine} actions=${html`<div class="flex flex-wrap gap-2">
        <${ui.Button} variant="secondary" onClick=${() => decaler(-1)}>Précédente</${ui.Button}>
        <${ui.Button} variant="ghost" onClick=${() => setDebut(lundiDe(new Date()))}>Aujourd'hui</${ui.Button}>
        <${ui.Button} variant="secondary" onClick=${() => decaler(1)}>Suivante</${ui.Button}>
      </div>`}>
        ${lignesEquipes.length === 0 ? html`<${ui.Empty} texte="Créez d'abord une équipe pour pouvoir planifier des passages." action=${html`<${ui.Button} variant="primary" onClick=${() => go("equipes")}>Aller aux équipes</${ui.Button}>`} />` : html`
        <div class="overflow-x-auto max-w-full">
          <div style="min-width: 1130px">
            <div class="grid" style=${GRILLE}>
              <div></div>
              ${jours.map((j) => html`<div key=${j.iso} class="px-2 py-2 text-center border-l border-[#A7F3D0] ${j.iso === aujourdhui ? "bg-[#ECFDF5]" : ""}">
                <div class="text-xs text-[#475569]">${j.label}</div>
                <div class="text-base font-semibold text-[#064E3B]">${j.num}</div>
              </div>`)}
            </div>
            ${lignesEquipes.map((e) => html`<div key=${e.id} class="grid border-t border-[#A7F3D0]" style=${GRILLE}>
              <div class="p-3 pr-2 min-w-0">
                <div class="text-sm font-semibold text-[#064E3B] break-words">${e.nom}</div>
                <div class="text-xs text-[#475569] break-words">${e.responsable || ""}</div>
              </div>
              ${jours.map((j) => html`<div key=${j.iso} class="min-w-0 flex flex-col">${cellule(e, j)}</div>`)}
            </div>`)}
          </div>
        </div>`}
      </${ui.Card}>
      </div>
      <div class="min-w-0">
      <${ui.Card} titre="Aujourd'hui">
        ${duJour.length === 0 ? html`<${ui.Empty} texte="Aucun passage aujourd'hui. Planifiez-en un." action=${html`<${ui.Button} variant="secondary" onClick=${() => ouvrir(null)}>Planifier</${ui.Button}>`} />` : html`
        <ul class="divide-y divide-[#A7F3D0]">
          ${duJour.map((i) => html`<li key=${i.id} class="py-3">
            <button onClick=${() => ouvrir(i)} class="block w-full text-left cursor-pointer focus:outline-none focus:ring-2 focus:ring-[var(--c)] rounded">
              <div class="text-sm font-medium text-[#064E3B] break-words">${i.heure_prevue || ""} · ${nomSite(i.site_id)}</div>
              <div class="text-xs text-[#475569] mb-1 break-words">${nomEquipe(i.equipe_id)}</div>
              <${ui.Badge} couleur=${couleurStatut(i.statut)}>${i.statut || "—"}</${ui.Badge}>
            </button>
          </li>`)}
        </ul>`}
      </${ui.Card}>
      </div>
    </div>`}
    <${ui.Modal} open=${!!edit} onClose=${() => setEdit(null)} titre=${edit && edit.id ? "Modifier le passage" : "Planifier un passage"}
      actions=${html`
        ${edit && edit.id ? html`<${ui.Button} variant="danger" onClick=${() => supprimer(edit)}>Supprimer</${ui.Button}>` : null}
        ${edit && edit.id && edit.statut !== "Annulée" ? html`<${ui.Button} variant="secondary" onClick=${() => { const i = edit; setEdit(null); annuler(i); }}>Annuler le passage</${ui.Button}>` : null}
        <${ui.Button} variant="primary" disabled=${busy} onClick=${enregistrer}>${busy ? "… en cours" : "Enregistrer"}</${ui.Button}>`}>
      <div class="space-y-3">
        <${ui.Select} label="Site client" value=${form.site_id} onChange=${maj("site_id")} options=${sitesRows.map((s) => [cle(s), s.nom])} />
        <${ui.Select} label="Équipe" value=${form.equipe_id} onChange=${maj("equipe_id")} options=${equipesRows.map((e) => [cle(e), e.nom])} />
        <div class="grid grid-cols-2 gap-3">
          <${ui.Input} label="Date" type="date" value=${form.date} onInput=${maj("date")} required />
          <${ui.Input} label="Heure prévue" type="time" value=${form.heure_prevue} onInput=${maj("heure_prevue")} />
        </div>
        <${ui.Input} label="Durée (minutes)" type="number" value=${form.duree_minutes} onInput=${maj("duree_minutes")} />
        ${edit && edit.id ? html`<${ui.Select} label="Statut" value=${form.statut} onChange=${maj("statut")} options=${["Planifiée", "En cours", "Terminée", "Annulée"].map((s) => [s, s])} />` : html`
        <label class="flex items-center gap-2 text-sm text-[#064E3B] min-h-[44px] cursor-pointer">
          <input type="checkbox" checked=${rappel} onChange=${(e) => setRappel(e.target.checked)} class="w-4 h-4 accent-[var(--c)]" />
          Envoyer un rappel par e-mail au contact du site la veille à 8 h
        </label>`}
        ${edit && edit.rappel_id ? html`<p class="text-xs text-[#475569]">Un rappel e-mail est programmé pour ce passage ; il sera annulé si vous le déplacez ou l'annulez.</p>` : null}
      </div>
    </${ui.Modal}>
  </${ui.Page}>`;
}

const STATUTS = ["À faire", "En vers", "Fait"];
const COULEUR = { "À faire": "gris", "En cours": "bleu", "Fait": "vert" };

function aujourdhui() {
  return new Date().toISOString().slice(0, 10);
}

function enRetard(t) {
  return t.statut !== "Fait" && t.echeance && t.echeance < aujourdhui();
}

function Ecran(props) {
  const taches = useCollection("taches");
  const sites = useCollection("sites");
  const interventions = useCollection("interventions");
  const [vue, setVue] = useState("liste");
  const [fSite, setFSite] = useState("");
  const [fStatut, setFStatut] = useState("");
  const [fEcheance, setFEcheance] = useState("");
  const [edition, setEdition] = useState(null);

  const nomSite = useCallback((id) => {
    const s = sites.rows.find((x) => x.id === id || x.ref === id);
    return s ? s.nom : "—";
  }, [sites.rows]);

  const idSite = (t) => {
    const s = sites.rows.find((x) => x.id === t.site_id || x.ref === t.site_id);
    return s ? s.id : t.site_id;
  };

  const filtrees = useMemo(() => {
    const auj = aujourdhui();
    const sem = new Date(Date.now() + 7 * 864e5).toISOString().slice(0, 10);
    return taches.rows.filter((t) => {
      if (fSite && idSite(t) !== fSite) return false;
      if (fStatut && t.statut !== fStatut) return false;
      if (fEcheance === "retard" && !enRetard(t)) return false;
      if (fEcheance === "jour" && t.echeance !== auj) return false;
      if (fEcheance === "semaine" && !(t.echeance && t.echeance >= auj && t.echeance <= sem)) return false;
      return true;
    });
  }, [taches.rows, sites.rows, fSite, fStatut, fEcheance]);

  const nbRetard = filtrees.filter(enRetard).length;
  const nbFait = filtrees.filter((t) => t.statut === "Fait").length;
  const nbOuvertes = filtrees.length - nbFait;

  const champs = useMemo(() => [
    { nom: "intitule", label: "Intitulé de la tâche", type: "texte", requis: true },
    { nom: "site_id", label: "Site client", type: "choix", options: sites.rows.map((s) => [s.id, s.nom]), requis: true },
    { nom: "intervention_id", label: "Intervention liée (facultatif)", type: "choix", options: [["", "Aucune"]].concat(interventions.rows.map((i) => [i.id, nomSite(i.site_id) + " · " + fmt.date(i.date)])) },
    { nom: "echeance", label: "Échéance", type: "date" },
    { nom: "statut", label: "Statut", type: "choix", options: STATUTS.map((s) => [s, s]).map((p) => p[0] === "En vers" ? ["En cours", "En cours"] : p) },
    { nom: "commentaire", label: "Commentaire", type: "long" },
  ], [sites.rows, interventions.rows]);

  const enregistrer = async (d) => {
    const data = Object.assign({}, d, { statut: d.statut || "À faire" });
    if (edition && edition.id) await taches.update(edition.id, data);
    else await taches.add(data);
    toast(edition && edition.id ? "Tâche modifiée" : "Tâche créée", "ok");
    setEdition(null);
  };

  const changerStatut = async (t, statut) => {
    await taches.update(t.id, { statut });
    toast("Statut mis à jour : " + statut, "ok");
  };

  const supprimer = async (t) => {
    if (!await demander("Supprimer la tâche « " + t.intitule + " » ?", { ok: "Supprimer", danger: true })) return;
    await taches.remove(t.id);
    toast("Tâche supprimée", "ok");
  };

  const suivant = (s) => (s === "À faire" ? "En cours" : s === "En cours" ? "Fait" : null);

  const colonnes = [
    { cle: "intitule", label: "Tâche", rendu: (t) => html`<div><div class="font-medium text-[#064E3B]">${t.intitule}</div>${t.commentaire ? html`<div class="text-xs text-[#475569] mt-0.5">${t.commentaire}</div>` : null}</div>` },
    { cle: "site_id", label: "Site", rendu: (t) => nomSite(t.site_id) },
    { cle: "echeance", label: "Échéance", rendu: (t) => html`<span class=${enRetard(t) ? "text-[#EA580C] font-semibold" : ""}>${t.echeance ? fmt.date(t.echeance) : "—"}</span>` },
    { cle: "statut", label: "Statut", rendu: (t) => html`<span class="inline-flex gap-1 flex-wrap"><${ui.Badge} couleur=${COULEUR[t.statut] || "gris"}>${t.statut}</${ui.Badge}>${enRetard(t) ? html`<${ui.Badge} couleur="orange">En retard</${ui.Badge}>` : null}</span>` },
    { cle: "actions", label: "Actions", rendu: (t) => html`<div class="flex gap-1 flex-wrap" onClick=${(e) => e.stopPropagation()}>
      ${suivant(t.statut) ? html`<${ui.Button} variant="secondary" onClick=${() => changerStatut(t, suivant(t.statut))}>${t.statut === "À faire" ? "Démarrer" : "Terminer"}</${ui.Button}>` : null}
      <${ui.Button} variant="ghost" onClick=${() => setEdition(t)}>Modifier</${ui.Button}>
      <${ui.Button} variant="ghost" onClick=${() => supprimer(t)}>Supprimer</${ui.Button}>
    </div>` },
  ];

  const kanbanCols = [["À faire", "À faire"], ["En cours", "En cours"], ["Fait", "Fait"]];
  const optSites = [["", "Tous les sites"]].concat(sites.rows.map((s) => [s.id, s.nom]));

  if (taches.loading || sites.loading) return html`<${ui.Page} titre="Tâches"><${ui.Loading} /></${ui.Page}>`;

  return html`<${ui.Page} titre="Tâches d'entretien"
    sous=${nbOuvertes + " tâche" + (nbOuvertes > 1 ? "s" : "") + " à traiter, dont " + nbRetard + " en retard, sur " + filtrees.length + " affichée" + (filtrees.length > 1 ? "s" : "") + "."}
    actions=${html`<${ui.Button} variant="primary" onClick=${() => setEdition({})}>Nouvelle tâche</${ui.Button}>`}>
    <div class="grid lg:grid-cols-[1fr_280px] gap-6">
      <div class="space-y-4 min-w-0">
        <div class="grid sm:grid-cols-3 gap-3">
          <${ui.Select} label="Site" value=${fSite} onChange=${setFSite} options=${optSites} />
          <${ui.Select} label="Statut" value=${fStatut} onChange=${setFStatut} options=${[["", "Tous les statuts"]].concat(kanbanCols)} />
          <${ui.Select} label="Échéance" value=${fEcheance} onChange=${setFEcheance} options=${[["", "Toutes les échéances"], ["retard", "En retard"], ["jour", "Aujourd'hui"], ["semaine", "7 prochains jours"]]} />
        </div>
        <${ui.Tabs} valeur=${vue} onChange=${setVue} onglets=${[["liste", "Liste"], ["etapes", "Par étapes"]]} />
        ${filtrees.length === 0
          ? html`<${ui.Empty} texte="Aucune tâche ne correspond. Créez votre première tâche d'entretien." action=${html`<${ui.Button} variant="primary" onClick=${() => setEdition({})}>Nouvelle tâche</${ui.Button}>`} />`
          : vue === "liste"
            ? html`<${ui.Table} colonnes=${colonnes} lignes=${filtrees} onClick=${(t) => setEdition(t)} vide="Aucune tâche." />`
            : html`<${ui.Kanban} colonnes=${kanbanCols} lignes=${filtrees} champ="statut" onDeplacer=${(id, v) => changerStatut({ id }, v)} onClick=${(t) => setEdition(t)}
                rendu=${(t) => html`<div class="text-sm"><div class="font-medium text-[#064E3B]">${t.intitule}</div><div class="text-xs text-[#475569]">${nomSite(t.site_id)}</div>${t.echeance ? html`<div class=${"text-xs mt-1 " + (enRetard(t) ? "text-[#EA580C] font-semibold" : "text-[#475569]")}>${enRetard(t) ? "En retard · " : ""}${fmt.date(t.echeance)}</div>` : null}</div>`} />`}
      </div>
      <div class="space-y-4">
        <${ui.Card} titre="Avancement">
          <${ui.Progress} valeur=${nbFait} max=${Math.max(filtrees.length, 1)} label=${nbFait + " faite" + (nbFait > 1 ? "s" : "") + " sur " + filtrees.length} />
        </${ui.Card}>
        <${ui.Card} titre="En retard">
          ${filtrees.filter(enRetard).length === 0
            ? html`<p class="text-sm text-[#475569]">Aucune tâche en retard.</p>`
            : html`<ul class="divide-y divide-[#A7F3D0]">${filtrees.filter(enRetard).map((t) => html`<li key=${t.id} class="py-3 flex items-center justify-between gap-2">
                <div class="min-w-0"><div class="text-sm font-medium truncate">${t.intitule}</div><div class="text-xs text-[#475569]">${nomSite(t.site_id)} · ${fmt.date(t.echeance)}</div></div>
                <${ui.Button} variant="secondary" onClick=${() => changerStatut(t, suivant(t.statut))}>Avancer</${ui.Button}>
              </li>`)}</ul>`}
        </${ui.Card}>
      </div>
    </div>
    <${ui.Modal} open=${!!edition} onClose=${() => setEdition(null)} titre=${edition && edition.id ? "Modifier la tâche" : "Nouvelle tâche"}>
      ${edition ? html`<${ui.Formulaire} champs=${champs} valeur=${edition.id ? edition : { statut: "À faire" }} onEnregistrer=${enregistrer} onAnnuler=${() => setEdition(null)} libelle=${edition.id ? "Enregistrer" : "Créer la tâche"} />` : null}
    </${ui.Modal}>
  </${ui.Page}>`;
}

const CHAMPS_EQUIPE = [
  { nom: "nom", label: "Nom de l'équipe", type: "texte", requis: true },
  { nom: "responsable", label: "Responsable", type: "texte" },
  { nom: "telephone", label: "Téléphone", type: "tel" },
  { nom: "agents", label: "Agents (séparés par des virgules)", type: "long" },
  { nom: "mission", label: "Mission de l'équipe", type: "long" },
  { nom: "actif", label: "Équipe active", type: "case" },
];

function listeAgents(texte) {
  return String(texte || "").split(",").map((a) => a.trim()).filter(Boolean);
}

function Ecran(props) {
  const equipes = useCollection("equipes");
  const interventions = useCollection("interventions");
  const sites = useCollection("sites");
  const [sel, setSel] = useState(null);
  const [edition, setEdition] = useState(null);
  const [filtre, setFiltre] = useState("actives");
  const [recherche, setRecherche] = useState("");

  const auj = new Date().toISOString().slice(0, 10);
  const nomSite = (id) => (sites.rows.find((s) => s.ref === id || s.id === id) || {}).nom || "Site inconnu";
  const deEquipe = (e) => interventions.rows.filter((i) => i.equipe_id === e.ref || i.equipe_id === e.id);
  const aVenir = (e) =>
    deEquipe(e)
      .filter((i) => i.date >= auj && i.statut !== "Terminée" && i.statut !== "Annulée")
      .sort((a, b) => (a.date + (a.heure_prevue || "")).localeCompare(b.date + (b.heure_prevue || "")));
  const sitesHabituels = (e) => {
    const cpt = {};
    deEquipe(e).forEach((i) => { cpt[i.site_id] = (cpt[i.site_id] || 0) + 1; });
    return Object.keys(cpt).sort((a, b) => cpt[b] - cpt[a]).map((id) => ({ id, nom: nomSite(id), n: cpt[id] }));
  };

  const visibles = useMemo(() => {
    const q = recherche.trim().toLowerCase();
    return equipes.rows.filter((e) => {
      if (filtre === "actives" && e.actif === false) return false;
      if (filtre === "inactives" && e.actif !== false) return false;
      if (!q) return true;
      return [e.nom, e.agents, e.responsable, e.mission].join(" ").toLowerCase().includes(q);
    });
  }, [equipes.rows, filtre, recherche]);

  const totalAgents = equipes.rows.filter((e) => e.actif !== false).reduce((n, e) => n + listeAgents(e.agents).length, 0);
  const totalPassages = equipes.rows.reduce((n, e) => n + aVenir(e).length, 0);

  const enregistrer = async (donnees) => {
    try {
      if (edition && edition.id) {
        await equipes.update(edition.id, donnees);
        toast("Équipe mise à jour", "ok");
      } else {
        await equipes.add({ actif: true, ...donnees });
        toast("Équipe créée", "ok");
      }
      setEdition(null);
    } catch (e) {
      toast(e.message || "Enregistrement impossible", "bad");
    }
  };

  const supprimer = async (e) => {
    if (!await demander("Supprimer l'équipe « " + e.nom + " » ?", { ok: "Supprimer", danger: true })) return;
    try {
      await equipes.remove(e.id);
      setSel(null);
      toast("Équipe supprimée", "ok");
    } catch (err) {
      toast(err.message, "bad");
    }
  };

  const basculer = async (e) => {
    await equipes.update(e.id, { actif: e.actif === false });
    toast(e.actif === false ? "Équipe réactivée" : "Équipe mise en pause", "ok");
  };

  const equipeSel = sel ? equipes.rows.find((e) => e.id === sel) : null;

  if (equipes.loading || interventions.loading || sites.loading) return html`<${ui.Page} titre="Équipes"><${ui.Loading} /></${ui.Page}>`;

  const carte = (e) => {
    const agents = listeAgents(e.agents);
    const prochains = aVenir(e);
    return html`
      <button key=${e.id} type="button" onClick=${() => setSel(e.id)}
        class="text-left w-full bg-white border border-[#A7F3D0] rounded-xl p-5 hover:border-[var(--c)] focus:outline-none focus-visible:ring-2 focus-visible:ring-[var(--c)] cursor-pointer min-h-[44px]">
        <div class="flex items-start justify-between gap-3">
          <div class="min-w-0">
            <div class="font-semibold text-[15px] text-[#064E3B] break-words">${e.nom}</div>
            <div class="text-sm text-[#475569] mt-1">Responsable : ${e.responsable || "non renseigné"}</div>
          </div>
          <${ui.Badge} couleur=${e.actif === false ? "gris" : "vert"}>${e.actif === false ? "En pause" : "Active"}</${ui.Badge}>
        </div>
        <p class="text-sm text-[#475569] mt-3 line-clamp-2">${e.mission || "Aucune mission décrite."}</p>
        <div class="flex flex-wrap gap-2 mt-4">
          ${agents.slice(0, 4).map((a) => html`<span key=${a} class="text-xs bg-[#ECFDF5] text-[#064E3B] border border-[#A7F3D0] rounded-full px-2.5 py-1">${a}</span>`)}
          ${agents.length > 4 ? html`<span class="text-xs text-[#475569] py-1">+${agents.length - 4}</span>` : null}
        </div>
        <div class="text-xs text-[#475569] mt-4 border-t border-[#A7F3D0] pt-3">
          ${agents.length} agent${agents.length > 1 ? "s" : ""} · ${prochains.length} passage${prochains.length > 1 ? "s" : ""} à venir
        </div>
      </button>`;
  };

  return html`
    <${ui.Page} titre="Équipes"
      sous=${equipes.rows.length + " équipe" + (equipes.rows.length > 1 ? "s" : "") + " pour " + totalAgents + " agents actifs, " + totalPassages + " passage" + (totalPassages > 1 ? "s" : "") + " à venir."}
      actions=${html`<${ui.Button} variant="primary" onClick=${() => setEdition({})}>Nouvelle équipe</${ui.Button}>`}>
      <div class="flex flex-col sm:flex-row gap-3 mb-5">
        <div class="flex-1">
          <${ui.Input} label="Rechercher" value=${recherche} onInput=${setRecherche} placeholder="Nom d'équipe, agent, responsable…" />
        </div>
        <div class="sm:w-56">
          <${ui.Select} label="Afficher" value=${filtre} onChange=${setFiltre}
            options=${[["actives", "Équipes actives"], ["inactives", "Équipes en pause"], ["toutes", "Toutes les équipes"]]} />
        </div>
      </div>
      ${visibles.length === 0
        ? html`<${ui.Empty} texte=${equipes.rows.length === 0 ? "Aucune équipe pour le moment. Créez votre première équipe et listez ses agents." : "Aucune équipe ne correspond à votre recherche."}
            action=${html`<${ui.Button} variant="primary" onClick=${() => setEdition({})}>Créer une équipe</${ui.Button}>`} />`
        : html`<div class="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">${visibles.map(carte)}</div>`}

      <${ui.Modal} open=${!!equipeSel} onClose=${() => setSel(null)} titre=${equipeSel ? equipeSel.nom : ""}
        actions=${equipeSel ? html`
          <${ui.Button} variant="secondary" onClick=${() => basculer(equipeSel)}>${equipeSel.actif === false ? "Réactiver" : "Mettre en pause"}</${ui.Button}>
          <${ui.Button} variant="secondary" onClick=${() => { setEdition(equipeSel); setSel(null); }}>Modifier</${ui.Button}>
          <${ui.Button} variant="danger" onClick=${() => supprimer(equipeSel)}>Supprimer</${ui.Button}>` : null}>
        ${equipeSel ? html`
          <div class="space-y-5 text-[#064E3B]">
            <div class="text-sm text-[#475569]">
              Responsable : <span class="text-[#064E3B] font-medium">${equipeSel.responsable || "non renseigné"}</span>
              ${equipeSel.telephone ? html` · <a class="underline cursor-pointer" href=${"tel:" + equipeSel.telephone.replace(/\s/g, "")}>${equipeSel.telephone}</a>` : null}
            </div>
            <div>
              <div class="font-semibold text-sm mb-2">Mission</div>
              <p class="text-sm text-[#475569]">${equipeSel.mission || "Aucune mission décrite."}</p>
            </div>
            <div>
              <div class="font-semibold text-sm mb-2">Agents (${listeAgents(equipeSel.agents).length})</div>
              <div class="flex flex-wrap gap-2">
                ${listeAgents(equipeSel.agents).length === 0 ? html`<span class="text-sm text-[#475569]">Aucun agent renseigné.</span>` : listeAgents(equipeSel.agents).map((a) => html`<span key=${a} class="text-sm bg-[#ECFDF5] border border-[#A7F3D0] rounded-full px-3 py-1">${a}</span>`)}
              </div>
            </div>
            <div>
              <div class="font-semibold text-sm mb-2">Sites habituels</div>
              ${sitesHabituels(equipeSel).length === 0
                ? html`<p class="text-sm text-[#475569]">Aucun passage enregistré pour cette équipe.</p>`
                : html`<ul class="divide-y divide-[#A7F3D0] border border-[#A7F3D0] rounded-lg">
                    ${sitesHabituels(equipeSel).map((s) => html`<li key=${s.id} class="flex justify-between gap-3 px-3 py-3 text-sm"><span class="min-w-0 break-words">${s.nom}</span><span class="text-[#475569] whitespace-nowrap">${s.n} passage${s.n > 1 ? "s" : ""}</span></li>`)}
                  </ul>`}
            </div>
            <div>
              <div class="font-semibold text-sm mb-2">Interventions à venir (${aVenir(equipeSel).length})</div>
              ${aVenir(equipeSel).length === 0
                ? html`<p class="text-sm text-[#475569]">Aucune intervention prévue.</p>`
                : html`<ul class="divide-y divide-[#A7F3D0] border border-[#A7F3D0] rounded-lg">
                    ${aVenir(equipeSel).slice(0, 8).map((i) => html`
                      <li key=${i.id} class="flex items-center justify-between gap-3 px-3 py-3 text-sm">
                        <div class="min-w-0">
                          <div class="break-words">${nomSite(i.site_id)}</div>
                          <div class="text-xs text-[#475569]">${fmt.date(i.date)}${i.heure_prevue ? " à " + i.heure_prevue : ""}${i.duree_minutes ? " · " + i.duree_minutes + " min" : ""}</div>
                        </div>
                        <${ui.Badge} couleur=${i.statut === "En cours" ? "orange" : "bleu"}>${i.statut}</${ui.Badge}>
                      </li>`)}
                  </ul>`}
              <div class="mt-3"><${ui.Button} variant="ghost" onClick=${() => go("planning")}>Ouvrir le planning</${ui.Button}></div>
            </div>
          </div>` : null}
      </${ui.Modal}>

      <${ui.Modal} open=${!!edition} onClose=${() => setEdition(null)} titre=${edition && edition.id ? "Modifier l'équipe" : "Nouvelle équipe"}>
        ${edition ? html`<${ui.Formulaire} champs=${CHAMPS_EQUIPE}
          valeur=${edition.id ? edition : { actif: true }}
          onEnregistrer=${enregistrer} onAnnuler=${() => setEdition(null)}
          libelle=${edition.id ? "Enregistrer" : "Créer l'équipe"} />` : null}
      </${ui.Modal}>
    </${ui.Page}>`;
}

function nomSite(sites, id) {
  const s = sites.find((x) => x.ref === id || x.id === id);
  return s ? s.nom : "Site inconnu";
}

function Ecran(props) {
  const rap = useCollection("rapports");
  const itv = useCollection("interventions");
  const sit = useCollection("sites");
  const equ = useCollection("equipes");
  const tac = useCollection("taches");
  const [modal, setModal] = useState(null);
  const [form, setForm] = useState({});
  const [onglet, setOnglet] = useState("a_envoyer");
  const [busy, setBusy] = useState(false);

  if (rap.loading || itv.loading || sit.loading || equ.loading || tac.loading) return html`<${ui.Loading} />`;

  const siteDe = (i) => sit.rows.find((s) => s.ref === i.site_id || s.id === i.site_id);
  const equipeDe = (i) => equ.rows.find((e) => e.ref === i.equipe_id || e.id === i.equipe_id);
  const itvDe = (r) => itv.rows.find((i) => i.ref === r.intervention_id || i.id === r.intervention_id);
  const envoyes = rap.rows.filter((r) => r.statut_envoi === "Envoyé");
  const brouillons = rap.rows.filter((r) => r.statut_envoi !== "Envoyé");
  const dejaRapporte = new Set(rap.rows.map((r) => r.intervention_id));
  const aRediger = itv.rows
    .filter((i) => i.statut === "Terminée" && !dejaRapporte.has(i.ref) && !dejaRapporte.has(i.id))
    .sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  const liste = onglet === "a_envoyer" ? brouillons : envoyes;

  const tachesDe = (i) => tac.rows.filter((t) => t.intervention_id === i.ref || t.intervention_id === i.id);

  const preparer = (i) => {
    const s = siteDe(i) || {};
    const taches = tachesDe(i);
    const faites = taches.filter((t) => t.statut === "Fait").length;
    const resume = taches.length ? `Tâches réalisées : ${faites} sur ${taches.length}.` : "";
    setForm({
      intervention_id: i.ref || i.id,
      site_id: i.site_id,
      date_passage: i.date,
      destinataire: s.contact_email || "",
      observations: resume,
    });
    setModal("nouveau");
  };

  const ouvrir = (r) => {
    setForm({ ...r });
    setModal("edition");
  };

  const set = (k) => (v) => setForm((f) => ({ ...f, [k]: v }));

  const contenuPdf = (r) => {
    const i = itvDe(r) || {};
    const s = siteDe({ site_id: r.site_id }) || {};
    const e = equipeDe(i) || {};
    const taches = tachesDe(i);
    return {
      titre: "Compte rendu de passage",
      sousTitre: `${s.nom || nomSite(sit.rows, r.site_id)} - ${fmt.date(r.date_passage)}`,
      emetteur: { titre: "Prestataire", lignes: [user.nom, user.email] },
      destinataire: { titre: "Client", lignes: [s.nom || "", s.contact_nom || "", s.adresse || ""] },
      lignes: [
        ["Date du passage", fmt.date(r.date_passage)],
        ["Équipe", e.nom || "-"],
        ["Heure prévue", i.heure_prevue || "-"],
        ["Arrivée", i.arrivee || "-"],
        ["Départ", i.depart || "-"],
      ],
      tableau: taches.length
        ? { colonnes: ["Tâche", "Statut", "Commentaire"], lignes: taches.map((t) => [t.intitule, t.statut, t.commentaire || ""]) }
        : undefined,
      paragraphes: [r.observations || "Aucune observation."],
      mentions: "Document généré par Conciergo.",
      nomFichier: `rapport-${(s.nom || "site").replace(/\s+/g, "-").toLowerCase()}-${r.date_passage}`,
    };
  };

  const enregistrer = async (statut) => {
    if (!form.destinataire) return avertir("Indiquez l'adresse e-mail du destinataire.");
    setBusy(true);
    try {
      const data = {
        intervention_id: form.intervention_id,
        site_id: form.site_id,
        date_passage: form.date_passage,
        destinataire: form.destinataire,
        observations: form.observations || "",
        statut_envoi: statut,
      };
      if (statut === "Envoyé") {
        const s = sit.rows.find((x) => x.ref === form.site_id || x.id === form.site_id) || {};
        await email({
          a: form.destinataire,
          sujet: `Compte rendu de passage - ${s.nom || ""} - ${fmt.date(form.date_passage)}`,
          texte: `Bonjour ${s.contact_nom || ""},\n\nVoici le compte rendu du passage du ${fmt.date(form.date_passage)} sur ${s.nom || "votre site"}.\n\n${form.observations || "Aucune observation particulière."}\n\nCordialement,\n${user.nom}`,
        });
        data.date_envoi = new Date().toISOString().slice(0, 10);
      }
      if (form.id) await rap.update(form.id, data);
      else await rap.add(data);
      toast(statut === "Envoyé" ? "Rapport envoyé au client" : "Brouillon enregistré", "ok");
      setModal(null);
    } catch (e) {
      toast(e.message || "Erreur", "bad");
    }
    setBusy(false);
  };

  const supprimer = async (r) => {
    if (!await demander("Supprimer ce rapport ?", { ok: "Supprimer", danger: true })) return;
    await rap.remove(r.id);
    setModal(null);
    toast("Rapport supprimé", "ok");
  };

  const telecharger = (r) => pdf(contenuPdf(r));

  const colonnes = [
    { cle: "date_passage", label: "Passage", rendu: (r) => fmt.date(r.date_passage) },
    { cle: "site_id", label: "Site", rendu: (r) => nomSite(sit.rows, r.site_id) },
    { cle: "destinataire", label: "Destinataire" },
    { cle: "statut_envoi", label: "Statut", rendu: (r) => html`<${ui.Badge} couleur=${r.statut_envoi === "Envoyé" ? "vert" : "orange"}>${r.statut_envoi || "Brouillon"}</${ui.Badge}>` },
    { cle: "date_envoi", label: "Envoyé le", rendu: (r) => (r.date_envoi ? fmt.date(r.date_envoi) : "-") },
  ];

  const sousTitre = `${aRediger.length} passage(s) terminé(s) sans rapport, ${brouillons.length} brouillon(s), ${envoyes.length} rapport(s) envoyé(s).`;

  return html`
    <${ui.Page} titre="Rapports de passage" sous=${sousTitre}>
      <div class="grid lg:grid-cols-[1fr_320px] gap-6">
        <div class="min-w-0">
          <${ui.Card} titre="Historique des rapports">
            <div class="mb-4">
              <${ui.Tabs} valeur=${onglet} onChange=${setOnglet} onglets=${[["a_envoyer", `Brouillons (${brouillons.length})`], ["envoyes", `Envoyés (${envoyes.length})`]]} />
            </div>
            <${ui.Table}
              colonnes=${colonnes}
              lignes=${liste}
              onClick=${ouvrir}
              vide=${onglet === "a_envoyer" ? "Aucun brouillon. Choisissez un passage terminé pour rédiger un rapport." : "Aucun rapport envoyé pour le moment."}
            />
          </${ui.Card}>
        </div>
        <div>
          <${ui.Card} titre="Passages à rapporter">
            ${aRediger.length === 0
              ? html`<p class="text-sm text-[#475569]">Tous les passages terminés ont un rapport.</p>`
              : html`<ul class="divide-y divide-[#A7F3D0]">
                  ${aRediger.map((i) => html`
                    <li key=${i.id} class="py-3 flex items-center justify-between gap-3">
                      <div class="min-w-0">
                        <div class="text-sm font-medium truncate">${nomSite(sit.rows, i.site_id)}</div>
                        <div class="text-xs text-[#475569]">${fmt.date(i.date)}</div>
                      </div>
                      <${ui.Button} variant="secondary" onClick=${() => preparer(i)}>Rédiger</${ui.Button}>
                    </li>`)}
                </ul>`}
          </${ui.Card}>
        </div>
      </div>

      <${ui.Modal}
        open=${!!modal}
        onClose=${() => setModal(null)}
        titre=${modal === "nouveau" ? "Nouveau compte rendu" : "Compte rendu de passage"}
        actions=${html`
          ${form.id && html`<${ui.Button} variant="danger" onClick=${() => supprimer(form)}>Supprimer</${ui.Button}>`}
          <${ui.Button} variant="secondary" disabled=${busy} onClick=${() => telecharger(form)}>Télécharger le PDF</${ui.Button}>
          <${ui.Button} variant="secondary" disabled=${busy} onClick=${() => enregistrer("Brouillon")}>Enregistrer le brouillon</${ui.Button}>
          <${ui.Button} variant="primary" disabled=${busy} onClick=${() => enregistrer("Envoyé")}>${busy ? "… en cours" : form.statut_envoi === "Envoyé" ? "Renvoyer" : "Envoyer au client"}</${ui.Button}>
        `}
      >
        <div class="space-y-4">
          <div class="text-sm text-[#475569]">
            ${nomSite(sit.rows, form.site_id)} - passage du ${form.date_passage ? fmt.date(form.date_passage) : "-"}
            ${form.statut_envoi === "Envoyé" && form.date_envoi ? ` - envoyé le ${fmt.date(form.date_envoi)}` : ""}
          </div>
          <${ui.Input} label="Destinataire" type="email" value=${form.destinataire || ""} onInput=${set("destinataire")} required=${true} />
          <${ui.Textarea} label="Observations" rows=${6} value=${form.observations || ""} onInput=${set("observations")} />
        </div>
      </${ui.Modal}>
    </${ui.Page}>
  `;
}
